That is, given a matrix $\mathbf{K}$, clustering by finding a scaling factor $c$ and a cluster probability matrix $\mathbf{G}$ that best solve
\begin{equation} \min_{c\geq 0, \mathbf{G}\succeq 0,\mathbf{G}\mathbb{1}_k = \mathbb{1}_n} \left\| \mathbf{K} - \frac{1}{c}\mathbf{GG}^\top \right\|_F^2.
\end{equation}

We prove by verifying the three conditions in Theorem \ref{thm:mainRes}: (a) $\mathbf{\Sigma}_{k-1}\mathbf{V}_{k-1}^\top=\mathbf{S}\mathbf{G}^\top$; 
	(b) $\mathbf{G}\mathbb{1}_k = \mathbb{1}_n$;
	(c) $\mathbf{G}\succeq 0$.

Thus, we are now interested in solving
\begin{equation} \min_{\substack{\mathbf{F},\mathbf{G}\mathbb{1}_k = \mathbb{1}_n \\ \mathbf{s}, \text{rank}(\mathbf{F}) \leq k-1 }} \| \mathbf{X} - \mathbf{s}\mathbb{1}_n^\top- \mathbf{FG}^\top\|_F^2.
\end{equation}

Plug the $\mathbf{G}_*$ in Lemma \ref{lem:optimizedG} into the objective function of Problem \eqref{eq:rankProblem} and use the easily checkable fact $\mathbf{F}\mathbf{\Phi} = \mathbf{U}\mathbf{U}^\top \left(\mathbf{X}-\mathbf{s}\mathbb{1}_n^\top\right), \mathbf{F}\mathbf{v}_\bot = 0$. We have
\[
\begin{aligned}
&\left\| \mathbf{X} - \mathbf{s}\mathbb{1}_n^\top- \mathbf{FG}^\top_*\right\|_F^2 \\
=& \left\| \mathbf{X} - \mathbf{s}\mathbb{1}_n^\top- \mathbf{F}\left(\mathbf{\Phi} 
+
\frac{\mathbf{v}_\bot\left(\mathbb{1}_n^\top - \mathbb{1}_k^\top \mathbf{\Phi} \right) }{\mathbb{1}_k^\top \mathbf{v}_\bot}\right) \right\|_F^2 \\
=& \left\| \mathbf{X} - \mathbf{s}\mathbb{1}_n^\top- \mathbf{U}\mathbf{U}^\top \left(\mathbf{X}-\mathbf{s}\mathbb{1}_n^\top\right) \right\|_F^2.
\end{aligned}
\]

Thus, we solve following problem with an $\epsilon > 0$ modification:
\begin{equation} \min_{\mathbf{F},\mathbf{G}\succeq 0,\mathbf{G}\mathbb{1}_k = \mathbb{1}_n} \| \mathbf{X} - \mathbf{FG}^\top\|_F^2 + \frac{\lambda}{2} \sum_{i=1}^k \log(\sigma_i^2(\mathbf{F}) + \varepsilon).
\end{equation}

The problem we concern in this subsection is 
\begin{equation} \min_{\substack{c,\mathbf{G}\succeq 0, \mathbf{G}\mathbb{1}_k = \mathbb{1}_n \\ \mathbf{K}^\prime \in \mathbb{K}(\mathbf{X}) } }
\| \mathbf{K}^\prime - \frac{1}{c}\mathbf{G}^\top\mathbf{G} \|_F^2
\end{equation}

According to rank$(\mathbf{H}\mathcal{K}\mathbf{H}) \leq k-1$, let $\mathbf{U}_\bot \in \mathbb{R}^{d\times (d-k+1)}$ be the orthocomplement of $\mathbf{U}_{k-1}$ and $\mathbf{m}=\mathbf{U}_\bot \mathbf{a}$ where $\mathbf{a} \in \mathbb{R}^{d-k+1}$. That is
	\[
	\begin{aligned}
	\mathbf{X}^\top\mathbf{X} &= \mathbf{P}^\top\left( \bar{\mathbf{F}}^\top\bar{\mathbf{F}} + \bar{\mathbf{F}}^\top \mathbf{m}\mathbb{1}_k^\top + \mathbb{1}_k\mathbf{m}^\top \bar{\mathbf{F}} + \|\mathbf{m}\|_2^2 \mathbb{1}_k\mathbb{1}_k^\top \right)\mathbf{P} \\
	&= \mathbf{P}^\top\left( \bar{\mathbf{F}}^\top\bar{\mathbf{F}} + \|\mathbf{m}\|_2^2 \mathbb{1}_k\mathbb{1}_k^\top \right)\mathbf{P} \\
	&= \mathbf{P}^\top\left( r^2k(k-1)\mathbf{BU}_{k-1}^\top\mathbf{U}_{k-1}\mathbf{B}^\top + \|\mathbf{m}\|_2^2 \mathbb{1}_k\mathbb{1}_k^\top \right)\mathbf{P} \\
	&= \mathbf{P}^\top\left( r^2k(k-1)\mathbf{B}\mathbf{B}^\top + \|\mathbf{m}\|_2^2 \mathbb{1}_k\mathbb{1}_k^\top \right)\mathbf{P} \\
	&= \mathbf{P}^\top\left( r^2k(k-1)\mathbb{I}_k - r^2(k-1) \mathbb{1}_k\mathbb{1}_k^\top + \|\mathbf{m}\|_2^2 \mathbb{1}_k\mathbb{1}_k^\top \right)\mathbf{P}
	\end{aligned}
	\]
